  private static final ConcurrentHashMap<Integer, VoxelShape> SHAPE_CACHE = new ConcurrentHashMap<>();

  public static Optional<VoxelShape> shapeFor(BlockState state) {
    if (state == null || state.isUnsupported()) return Optional.empty();
    Spec spec = SPECS.get(state.blockId());
    if (spec == null) return Optional.empty();
    int shapeId;
    if (spec.shapeIds().length == 1) {
      shapeId = spec.shapeIds()[0];
    } else {
      int index = 0;
      for (int property = 0; property < spec.names().length; property++) {
        String value = state.properties().get(spec.names()[property]);
        if (value == null) return Optional.empty();
        String[] allowed = spec.values()[property];
        int valueIndex = -1;
        for (int i = 0; i < allowed.length; i++) {
          if (allowed[i].equals(value)) { valueIndex = i; break; }
        }
        if (valueIndex < 0) return Optional.empty();
        index = index * allowed.length + valueIndex;
      }
      if (index < 0 || index >= spec.shapeIds().length) return Optional.empty();
      shapeId = spec.shapeIds()[index];
    }
    return Optional.of(shape(shapeId));
  }

  public static boolean knowsBlock(String blockId) {
    return SPECS.containsKey(blockId);
  }

  private static VoxelShape shape(int shapeId) {
    return SHAPE_CACHE.computeIfAbsent(shapeId, BlockCollisionCatalogue12111::buildShape);
  }

  private static VoxelShape buildShape(int shapeId) {
    if (shapeId < 0 || shapeId + 1 >= SHAPE_OFFSETS.length) {
      throw new IllegalArgumentException("unknown collision shape id " + shapeId);
    }
    int start = SHAPE_OFFSETS[shapeId];
    int end = SHAPE_OFFSETS[shapeId + 1];
    ArrayList<BlockBox> boxes = new ArrayList<>((end - start) / 6);
    for (int i = start; i < end; i += 6) {
      boxes.add(new BlockBox(
          SHAPE_COORDS[i] / 32.0, SHAPE_COORDS[i + 1] / 32.0, SHAPE_COORDS[i + 2] / 32.0,
          SHAPE_COORDS[i + 3] / 32.0, SHAPE_COORDS[i + 4] / 32.0, SHAPE_COORDS[i + 5] / 32.0));
    }
    return VoxelShape.localUnbounded(boxes);
  }
